SELECT CASE WHEN unit_price >= 430 THEN 'high' WHEN unit_price >= 110 THEN 'mid' ELSE 'low' END AS unit_price_bucket, AVG(quantity) AS avg_quantity FROM order_items GROUP BY CASE WHEN unit_price >= 430 THEN 'high' WHEN unit_price >= 110 THEN 'mid' ELSE 'low' END ORDER BY unit_price_bucket LIMIT 10;
